      <div class="card-actions"><a href="/books/${book.id}" class="text-link">View book ${icon('arrow', 16)}</a>${book.status === 'reading' ? `<form action="/books/${book.id}/finish" method="post"><button class="finish-link" type="submit">${icon('check', 16)} Mark finished</button></form>` : ''}</div>
    </div>
  </article>`;
}

function homePage(books) {
  const reading = books.filter(book => book.status === 'reading').sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  const finished = books.filter(book => book.status === 'finished').sort((a, b) => (b.finishedAt || '').localeCompare(a.finishedAt || ''));
  return layout('My library', 'library', `
    <header class="topbar"><span class="eyebrow">YOUR PERSONAL LIBRARY <span class="eyebrow-line"></span> YOUR STORY SO FAR</span><a class="button button-dark top-add" href="/books/new">${icon('plus', 18)} Add a book</a></header>
    <div class="page-heading"><div><p class="kicker">A LITTLE SPACE FOR BIG STORIES</p><h1>Your reading <em>life,</em><br>all in one place<span class="period">.</span></h1><p class="heading-subtitle">The books you're in the middle of, the ones you'll never forget, and everything in between.</p></div><div class="heading-spark" aria-hidden="true">✳</div></div>
    <div class="summary-strip" aria-label="Library summary"><div class="summary-intro">THE SHELF, AT A GLANCE <span>↗</span></div><div class="summary-stat"><strong>${reading.length}</strong><span>Currently reading</span></div><div class="summary-stat"><strong>${finished.length}</strong><span>Finished books</span></div><div class="summary-stat"><strong>${books.length}</strong><span>On your shelf</span></div></div>
    <section class="shelf-section" id="reading"><div class="section-heading"><div><span class="section-index">01 / THE NOW</span><h2>Currently reading<span class="heading-period">.</span></h2><p>Pick up right where you left off.</p></div><span class="section-count">${String(reading.length).padStart(2, '0')} BOOK${reading.length === 1 ? '' : 'S'}</span></div>
      ${reading.length ? `<div class="book-grid">${reading.map(bookCard).join('')}</div>` : `<div class="empty-reading"><div class="empty-copy"><span class="empty-star">✳</span><h3>A good story<br>starts <em>somewhere.</em></h3><p>Your shelf is waiting. Add the book you're reading and let the story begin.</p><a class="button button-light" href="/books/new">Add your first book ${icon('arrow', 17)}</a></div><div class="empty-art" aria-hidden="true"><div class="art-halo"></div><div class="art-book art-book-one"><span>STORIES<br>TO KEEP</span><small>✳</small></div><div class="art-book art-book-two"><span>THE<br>NEXT<br>CHAPTER</span><small>✳</small></div><div class="art-book art-book-three"><span>BEYOND<br>THE PAGE</span><small>✳</small></div><div class="art-ground"></div></div></div>`}
    </section>
    <section class="shelf-section finished-section" id="finished"><div class="section-heading"><div><span class="section-index">02 / THE ARCHIVE</span><h2>Finished books<span class="heading-period">.</span></h2><p>Stories that stay with you.</p></div><span class="section-count">${String(finished.length).padStart(2, '0')} BOOK${finished.length === 1 ? '' : 'S'}</span></div>
      ${finished.length ? `<div class="book-grid">${finished.map(bookCard).join('')}</div>` : `<div class="empty-finished">${icon('book', 25)}<span>Your finished books will find a home here.</span><span class="empty-finished-star">✳</span></div>`}
    </section>`);
}

function formPage(values = {}, error = '') {
  const title = values.title || '';
  const author = values.author || '';
  const notes = values.notes || '';
  return layout('Add a book', 'new', `<header class="topbar"><span class="eyebrow">YOUR PERSONAL LIBRARY <span class="eyebrow-line"></span> A NEW STORY</span><a href="/" class="top-back">${icon('back', 17)} Back to library</a></header>
    <div class="form-layout"><div class="form-intro"><p class="kicker">A NEW ADDITION</p><h1>Make room for<br><em>another story.</em><span class="period">✳</span></h1><p class="heading-subtitle">What are you reading? Give it a spot on your shelf. You can always come back to your notes later.</p><div class="form-decoration" aria-hidden="true"><span>“</span><p>There is no friend as loyal as a book.</p><small>— ERNEST HEMINGWAY</small></div></div>
    <div class="form-panel"><span class="form-panel-label">01 / BOOK DETAILS</span><h2>Add a book<span class="heading-period">.</span></h2><p>Just the essentials to get started.</p>
      ${error ? `<div class="form-error" role="alert">${escapeHtml(error)}</div>` : ''}
      <form action="/books" method="post" class="book-form">
        <label for="title">Book title <span>*</span></label><input id="title" name="title" type="text" required maxlength="200" placeholder="e.g. The Secret History" value="${escapeHtml(title)}" autofocus>
        <label for="author">Author <span>*</span></label><input id="author" name="author" type="text" required maxlength="200" placeholder="e.g. Donna Tartt" value="${escapeHtml(author)}">
        <label for="notes">Your notes <span class="optional">OPTIONAL</span></label><textarea id="notes" name="notes" rows="6" maxlength="10000" placeholder="A thought, a favorite line, or something you want to remember...">${escapeHtml(notes)}</textarea><p class="field-hint">A little space for whatever stays with you.</p>
        <div class="form-actions"><button type="submit" class="button button-dark">Add to my shelf ${icon('arrow', 17)}</button><a href="/" class="cancel-link">Cancel</a></div>
      </form></div></div>`);
}

function formatDate(value) {
  if (!value) return '';
  return new Date(value).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric', timeZone: 'UTC' });
}

function detailPage(book) {
  return layout(book.title, 'library', `<header class="topbar"><span class="eyebrow">YOUR PERSONAL LIBRARY <span class="eyebrow-line"></span> BOOK DETAILS</span><a href="/" class="top-back">${icon('back', 17)} Back to library</a></header>
    <div class="detail-breadcrumb"><a href="/">My library</a><span>/</span><span>${escapeHtml(book.title)}</span></div>
    <div class="detail-layout"><div class="detail-art"><div class="detail-cover-frame">${cover(book, 'large')}</div><div class="detail-art-caption">A STORY WORTH KEEPING <span>✳</span></div></div>
    <article class="detail-info"><div class="detail-status">${badge(book.status)}<span class="detail-number">ON YOUR SHELF</span></div><p class="kicker">A BOOK ON YOUR SHELF</p><h1>${escapeHtml(book.title)}<span class="period">.</span></h1><p class="detail-author">by <strong>${escapeHtml(book.author)}</strong></p><div class="detail-divider"></div>
      <div class="detail-metadata"><div><span>ADDED TO SHELF</span><strong>${formatDate(book.createdAt)}</strong></div><div><span>READING STATUS</span><strong>${book.status === 'finished' ? 'Finished' : 'Currently reading'}</strong></div>${book.finishedAt ? `<div><span>FINISHED ON</span><strong>${formatDate(book.finishedAt)}</strong></div>` : ''}</div>
      <div class="notes-section"><div class="notes-heading">${icon('feather', 20)}<h2>My notes</h2></div>${book.notes ? `<p class="notes-text">${escapeHtml(book.notes)}</p>` : '<p class="notes-placeholder">No notes for this one yet.</p>'}</div>
      <div class="detail-actions">${book.status === 'reading' ? `<form action="/books/${book.id}/finish" method="post"><button class="button button-dark" type="submit">${icon('check', 18)} Mark as finished</button></form>` : ''}<button class="button button-outline" type="button" data-copy-link>${icon('link', 18)} <span>Copy book link</span></button></div>
    </article></div>`, `Notes and reading status for ${book.title} by ${book.author}.`);
}

function errorPage(code, heading, message) {
  return layout(heading, 'library', `<header class="topbar"><span class="eyebrow">BETWEEN PAGES</span></header><div class="not-found"><span class="not-found-number">${code}</span><h1>${escapeHtml(heading)}<span class="period">.</span></h1><p>${escapeHtml(message)}</p><a href="/" class="button button-dark">${icon('back', 17)} Back to library</a></div>`);
}

function respond(res, status, html, headers = {}) {
  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8', ...headers });
  res.end(html);
}

async function readBooks(dataFile) {
  try {
    const books = JSON.parse(await readFile(dataFile, 'utf8'));
    if (!Array.isArray(books)) throw new Error('Books file must contain an array');
    return books;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}

function makeStore(dataFile) {
  let queue = Promise.resolve();
  return {
    list: () => readBooks(dataFile),
    update: fn => {
      const operation = queue.then(async () => {
        const books = await readBooks(dataFile);
        const result = fn(books);
        await mkdir(dirname(dataFile), { recursive: true });
        const temp = `${dataFile}.${randomUUID()}.tmp`;
        try {
          await writeFile(temp, JSON.stringify(books, null, 2) + '\n');
          await rename(temp, dataFile);
        } catch (error) {
          await unlink(temp).catch(() => {});
          throw error;
        }
        return result;
      });
      queue = operation.catch(() => {});
      return operation;
    },
  };
}

async function parseForm(req) {
  let text = '';
  for await (const chunk of req) {
    text += chunk;
    if (text.length > 40000) throw new Error('Form is too large.');
  }
  return Object.fromEntries(new URLSearchParams(text));
}

export function createApp({ dataFile = defaultDataFile } = {}) {
  const store = makeStore(dataFile);
  return http.createServer(async (req, res) => {
    try {
      const path = new URL(req.url, 'http://localhost').pathname;
      if (req.method === 'GET' && (path === '/styles.css' || path === '/app.js')) {
        const file = path === '/styles.css' ? 'styles.css' : 'app.js';
        res.writeHead(200, { 'Content-Type': path.endsWith('.css') ? 'text/css; charset=utf-8' : 'text/javascript; charset=utf-8', 'Cache-Control': 'public, max-age=3600' });
        res.end(await readFile(resolve(root, file)));
        return;
      }
      if (req.method === 'GET' && path === '/') return respond(res, 200, homePage(await store.list()));
      if (req.method === 'GET' && path === '/books/new') return respond(res, 200, formPage());
      if (req.method === 'POST' && path === '/books') {
        const values = await parseForm(req);
        const title = (values.title || '').trim();
        const author = (values.author || '').trim();
        const notes = (values.notes || '').trim();
        if (!title || !author || title.length > 200 || author.length > 200 || notes.length > 10000) {
          return respond(res, 400, formPage(values, 'Please add a title and author (up to 200 characters each). Notes can be up to 10,000 characters.'));
        }
        const book = { id: randomUUID(), title, author, notes, status: 'reading', createdAt: new Date().toISOString(), finishedAt: null };
        await store.update(books => books.push(book));
        res.writeHead(303, { Location: `/books/${book.id}` });
        return res.end();
      }
      const detail = path.match(/^\/books\/([0-9a-f-]{36})$/i);
      if (req.method === 'GET' && detail) {
        const book = (await store.list()).find(item => item.id === detail[1]);
        return book ? respond(res, 200, detailPage(book)) : respond(res, 404, errorPage(404, 'Book not found', 'That book isn’t on this shelf.'));
      }
      const finish = path.match(/^\/books\/([0-9a-f-]{36})\/finish$/i);
      if (req.method === 'POST' && finish) {
        const books = await store.list();
        if (!books.some(book => book.id === finish[1])) return respond(res, 404, errorPage(404, 'Book not found', 'That book isn’t on this shelf.'));
        await store.update(items => {
          const book = items.find(item => item.id === finish[1]);
          if (book && book.status !== 'finished') {
            book.status = 'finished';
            book.finishedAt = new Date().toISOString();
          }
        });
        res.writeHead(303, { Location: `/books/${finish[1]}` });
        return res.end();
      }
      return respond(res, 404, errorPage(404, 'Page not found', 'The page you’re looking for isn’t here.'));
    } catch (error) {
      if (error.message === 'Form is too large.') return respond(res, 413, errorPage(413, 'Too much to carry', error.message));
      console.error(error);
      if (!res.headersSent) respond(res, 500, errorPage(500, 'Something went wrong', 'Please try again in a moment.'));
      else res.end();
    }
  });
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const port = Number(process.env.PORT) || 3000;
  createApp().listen(port, () => console.log(`Between Pages is running at http://localhost:${port}`));
}
"}

