.shelf-section{scroll-margin-top:30px}.section-heading{display:flex;justify-content:space-between;align-items:end;margin:0 0 25px}.section-index{color:#be805f;font-size:9px}.section-heading h2{font:400 34px/1.2 var(--serif);letter-spacing:-.6px;margin:8px 0 5px}.section-heading p{font-size:12px;color:#8d948a;margin:0}.section-count{color:#9aa296;margin-bottom:5px;font-size:9px}.finished-section{margin-top:58px}
