.empty-finished{height:105px;border:1px dashed #d9ded3;border-radius:7px;display:flex;align-items:center;gap:17px;padding:0 24px;background:#fbfaf5;color:#969f94;font-size:12px}.empty-finished svg{color:#8fa193}.empty-finished-star{margin-left:auto;font-size:24px;color:#d5ddce}
