import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createApp } from './server.js';

async function start(dataFile) {
  const server = createApp({ dataFile });
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
  return {
    url: `http://127.0.0.1:${server.address().port}`,
    close: () => new Promise(resolve => server.close(resolve)),
  };
}

test('books can be added, viewed, finished, shared by URL, and survive a restart', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'between-pages-'));
  const dataFile = join(dir, 'books.json');
  let app;
  try {
    app = await start(dataFile);
    let response = await fetch(app.url);
    assert.equal(response.status, 200);
    assert.match(await response.text(), /Currently reading/);

    response = await fetch(`${app.url}/books`, {
      method: 'POST', redirect: 'manual',
      body: new URLSearchParams({ title: 'The <Book> & More', author: 'A. Writer', notes: 'A note\nwith <script>alert(1)</script>' }),
    });
    assert.equal(response.status, 303);
    const location = response.headers.get('location');
    assert.match(location, /^\/books\/[a-f0-9-]{36}$/);

    response = await fetch(`${app.url}${location}`);
    const detail = await response.text();
    assert.equal(response.status, 200);
    assert.match(detail, /The &lt;Book&gt; &amp; More/);
    assert.match(detail, /A note\nwith &lt;script&gt;alert\(1\)&lt;\/script&gt;/);
    assert.doesNotMatch(detail, /<script>alert\(1\)<\/script>/);

    response = await fetch(app.url);
    assert.match(await response.text(), /The &lt;Book&gt; &amp; More/);

    response = await fetch(`${app.url}${location}/finish`, { method: 'POST', redirect: 'manual' });
    assert.equal(response.status, 303);
    assert.equal(response.headers.get('location'), location);
    const books = JSON.parse(await readFile(dataFile, 'utf8'));
    assert.equal(books.length, 1);
    assert.equal(books[0].status, 'finished');
    assert.ok(books[0].finishedAt);

    await app.close();
    app = await start(dataFile);
    response = await fetch(`${app.url}${location}`);
    assert.equal(response.status, 200);
    assert.match(await response.text(), /Finished/);
    response = await fetch(app.url);
    const home = await response.text();
    assert.match(home, /Finished books/);
    assert.match(home, /The &lt;Book&gt; &amp; More/);
  } finally {
    if (app) await app.close();
    await rm(dir, { recursive: true, force: true });
  }
});

test('validation, missing books, and simultaneous additions', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'between-pages-'));
  const dataFile = join(dir, 'books.json');
  const app = await start(dataFile);
  try {
    let response = await fetch(`${app.url}/books`, { method: 'POST', body: new URLSearchParams({ title: '  ', author: 'Someone' }) });
    assert.equal(response.status, 400);
    assert.match(await response.text(), /Please add a title and author/);

    const additions = await Promise.all(Array.from({ length: 5 }, (_, index) => fetch(`${app.url}/books`, {
      method: 'POST', redirect: 'manual',
      body: new URLSearchParams({ title: `Book ${index}`, author: 'Writer' }),
    })));
    assert.ok(additions.every(result => result.status === 303));
    assert.equal(JSON.parse(await readFile(dataFile, 'utf8')).length, 5);

    response = await fetch(`${app.url}/books/00000000-0000-0000-0000-000000000000`);
    assert.equal(response.status, 404);
    response = await fetch(`${app.url}/books/00000000-0000-0000-0000-000000000000/finish`, { method: 'POST' });
    assert.equal(response.status, 404);
  } finally {
    await app.close();
    await rm(dir, { recursive: true, force: true });
  }
});

