async function parseForm(req) {
  let text = '';
  for await (const chunk of req) {
    text += chunk;
    if (text.length > 40000) throw new Error('Form is too large.');
  }
  return Object.fromEntries(new URLSearchParams(text));
}

args.new_string:
async function parseForm(req) {
  const chunks = [];
  let bytes = 0;
  for await (const chunk of req) {
    bytes += chunk.length;
    if (bytes > 40000) throw new Error('Form is too large.');
    chunks.push(chunk);
  }
  return Object.fromEntries(new URLSearchParams(Buffer.concat(chunks).toString('utf8')));
}

